    for (int i = 0; i < M; i++) {
        if (A[i] == '1') {
            int r = up[i];
            if (r <= N) {
                painted += (N - r + 1);
                up[i] = N + 1;
            }
        }
    }
    // Process from bottom: B
    for (int i = 0; i < M; i++) {
        if (B[i] == '1') {
            int r = down[i];
            if (r >= 1) {
                painted += (r);
                down[i] = 0;
            }
        }
    }
    // Process from left: C
    for (int j = 0; j < N; j++) {
        if (C[j] == '1') {
            int c = left[j];
            if (c <= M) {
                painted += (M - c + 1);
                left[j] = M + 1;
            }
        }
    }
    // Process from right: D
    for (int j = 0; j < N; j++) {
